import * as BABYLON from 'babylonjs';
import { townStrip, RGB, CardboardImage } from '../art/CardboardArt';

/**
 * CARDBOARD TOWN — seamless parallax built from IMAGE TEXTURES on flat planes.
 *
 * Geometry is intentionally near-zero: every layer is a handful of textured
 * planes. All the photoreal hand-crafted charm (paper fibre, die-cut houses,
 * glowing windows, awnings, bunting, tape) lives in the PBR albedo + normal
 * maps generated by CardboardArt. Nothing here is modelled in 3D.
 */
export class CardboardTownParallax {
  private scene: BABYLON.Scene;
  private centerX: number;
  private layers: { tiles: BABYLON.Mesh[]; tileWidth: number; speed: number }[] = [];
  private disposables: BABYLON.Material[] = [];
  private textures: BABYLON.Texture[] = [];
  private clouds: BABYLON.Mesh[] = [];
  private skyMesh!: BABYLON.Mesh;
  private t = 0;

  constructor(scene: BABYLON.Scene, centerX: number, accent: RGB) {
    this.scene = scene;
    this.centerX = centerX;

    // Sky gradient — a single flat plane, painted image only.
    this.sky();

    // Town layers — each is the SAME seamless image strip, tinted per depth.
    // Far skyline: hazy and slow. Mid: full neighbourhood. Near: richer/larger.
    const far = townStrip(scene, 11, 0, [[0.32, 0.36, 0.46], [0.38, 0.4, 0.5], [0.28, 0.3, 0.4]]);
    const mid = townStrip(scene, 23, 1, [[0.78, 0.6, 0.4], [0.36, 0.72, 0.62], [0.9, 0.82, 0.6]]);
    const near = townStrip(scene, 37, 2, [[0.86, 0.68, 0.46], [0.4, 0.78, 0.68], [0.94, 0.86, 0.64]]);
    this.images.push(far, mid, near);

    // Camera sits at z=-44 looking toward +Z; the play plane is z=0. All
    // backdrop planes therefore sit at POSITIVE z, behind the skater.
    // Tile width / plane height MUST match the 2048x768 strip aspect (2.667)
    // so round clocks, gauges and windows render as circles, not ovals.
    this.addLayer('far', 123, 0.12, 150, far, 0.78, 46, 34);
    this.addLayer('mid', 144, 0.3, 95, mid, 1.0, 54, 28);
    this.addLayer('near', 160, 0.58, 50, near, 1.12, 60, 22);

    this.cloudsAndMotes(accent);
  }

  private images: CardboardImage[] = [];

  private sky() {
    const cv = document.createElement('canvas');
    cv.width = 8; cv.height = 512;
    const ctx = cv.getContext('2d')!;
    const g = ctx.createLinearGradient(0, 0, 0, 512);
    // Warm hazy kraft-gold, matching the reference cardboard diorama.
    g.addColorStop(0.0, '#8a6a49');
    g.addColorStop(0.35, '#b8936a');
    g.addColorStop(0.6, '#d6b183');
    g.addColorStop(0.82, '#edcd9c');
    g.addColorStop(1.0, '#f6e2bd');
    ctx.fillStyle = g; ctx.fillRect(0, 0, 8, 512);
    const tex = new BABYLON.Texture(cv.toDataURL(), this.scene, false, true);
    this.textures.push(tex);
    const mat = new BABYLON.StandardMaterial('cbSky', this.scene);
    mat.emissiveTexture = tex;
    mat.disableLighting = true;
    mat.backFaceCulling = false;
    this.disposables.push(mat);
    const band = BABYLON.MeshBuilder.CreatePlane('cbSkyBand', { width: 2400, height: 1100 }, this.scene);
    band.position.set(this.centerX, 120, 260);
    band.material = mat;
    band.isPickable = false;
    this.skyMesh = band;
    // NOT added to the wrapping layers — it tracks the camera exactly so its
    // edge can never scroll into view.
  }

  private addLayer(name: string, tileWidth: number, speed: number, z: number,
                   image: CardboardImage,
                   tint: number, height: number, y: number) {
    const mat = new BABYLON.PBRMaterial(`cbMat_${name}`, this.scene);
    mat.albedoTexture = image.albedo;
    mat.bumpTexture = image.normal;
    (mat.bumpTexture as BABYLON.Texture).level = 0.7;
    image.albedo.hasAlpha = true;
    mat.useAlphaFromAlbedoTexture = true;
    mat.transparencyMode = BABYLON.Material.MATERIAL_ALPHABLEND;
    mat.albedoColor = new BABYLON.Color3(tint, tint, tint);
    // Only the painted lit windows live in the emissive map → the glow layer
    // blooms them as cozy candlelight without extra geometry or occlusion.
    mat.emissiveTexture = image.emissive ?? image.albedo;
    mat.emissiveColor = new BABYLON.Color3(1.15, 0.9, 0.6);
    mat.metallic = 0;
    mat.roughness = 0.95;
    mat.environmentIntensity = 0.35;
    mat.backFaceCulling = false;
    mat.disableDepthWrite = false;
    this.disposables.push(mat);

    const count = 9;
    const tiles: BABYLON.Mesh[] = [];
    for (let i = 0; i < count; i++) {
      const plane = BABYLON.MeshBuilder.CreatePlane(`cb_${name}_${i}`, { width: tileWidth, height }, this.scene);
      plane.position.set(this.centerX + (i - Math.floor(count / 2)) * tileWidth, y, z);
      plane.material = mat;
      plane.isPickable = false;
      tiles.push(plane);
    }
    this.layers.push({ tiles, tileWidth, speed });
  }

  /** A few textured cloud puffs + motes (still planes/boxes, no modelling). */
  private cloudsAndMotes(accent: RGB) {
    const W = 256, H = 128;
    const cv = document.createElement('canvas');
    cv.width = W; cv.height = H;
    const ctx = cv.getContext('2d')!;
    ctx.clearRect(0, 0, W, H);
    const g = ctx.createRadialGradient(W / 2, H / 2, 4, W / 2, H / 2, W / 2);
    g.addColorStop(0, 'rgba(255,246,232,0.85)');
    g.addColorStop(1, 'rgba(255,246,232,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(W / 2, H / 2, H * 0.42, 0, Math.PI * 2); ctx.fill();
    const tex = new BABYLON.Texture(cv.toDataURL(), this.scene, false, true);
    tex.hasAlpha = true;
    this.textures.push(tex);
    const mat = new BABYLON.StandardMaterial('cbCloud', this.scene);
    mat.diffuseTexture = tex;
    mat.emissiveTexture = tex;
    mat.opacityTexture = tex;
    (mat.opacityTexture as BABYLON.Texture).getAlphaFromRGB = false;
    mat.useAlphaFromDiffuseTexture = true;
    mat.diffuseColor = BABYLON.Color3.Black();
    mat.disableLighting = true;
    mat.backFaceCulling = false;
    mat.transparencyMode = BABYLON.Material.MATERIAL_ALPHABLEND;
    this.disposables.push(mat);
    for (let i = 0; i < 8; i++) {
      const cloud = BABYLON.MeshBuilder.CreatePlane('cbCloud', { width: 34, height: 17 }, this.scene);
      cloud.position.set(this.centerX - 240 + i * 62, 52 + (i % 3) * 12, 120 + (i % 2) * 30);
      cloud.material = mat;
      cloud.isPickable = false;
      (cloud as any)._drift = i;
      this.clouds.push(cloud);
      this.layers.push({ tiles: [cloud], tileWidth: 1000, speed: 0.06 });
    }
    void accent;
  }

  public update(dt: number) {
    this.t += dt;
    for (const c of this.clouds) c.position.y += Math.sin(this.t * 0.3 + (c as any)._drift) * dt * 0.25;
  }

  public scroll(camX: number) {
    // Sky is anchored to the camera — its edge can never enter the view.
    this.skyMesh.position.x = camX;
    for (const layer of this.layers) {
      const w = layer.tileWidth;
      const shift = camX * (1 - layer.speed);
      const wrapped = ((shift % w) + w) % w;
      const n = layer.tiles.length;
      const half = Math.floor(n / 2);
      for (let i = 0; i < n; i++) {
        layer.tiles[i].position.x = camX + (i - half) * w - wrapped;
      }
    }
  }

  public dispose() {
    this.skyMesh.dispose(false, false);
    for (const l of this.layers) for (const t of l.tiles) t.dispose(false, false);
    for (const img of this.images) { img.albedo.dispose(); img.normal.dispose(); }
    for (const m of this.disposables) m.dispose();
    for (const t of this.textures) t.dispose();
    this.layers = [];
    this.clouds = [];
  }
}
